<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import Icon from '../components/BabyAppIcon.vue'
import NurseryScene from '../components/NurseryScene.vue'
import ConsumerPlatformPanel from '../components/ConsumerPlatformPanel.vue'
const platformMode = ref(true), platformName = ref('')
const platformPanel = ref<InstanceType<typeof ConsumerPlatformPanel>>()

type Tab = 'home' | 'monitor' | 'events' | 'profile'
type Notice = { id: number; title: string; detail: string; time: string; kind: string }
const tab = ref<Tab>('home'), sheet = ref(''), toast = ref(''), night = ref(false), paused = ref(false)
const expanded = ref(false), sound = ref(false), music = ref(false), recording = ref(false), talking = ref(false)
const deviceName = ref('宝宝的房间'), extraDevice = ref(''), newName = ref('儿童房监视器'), deviceType = ref('婴儿监视器')
const cryAlerts = ref(true), motionAlerts = ref(true), temperatureAlerts = ref(true), sensitivity = ref('适中')
const filter = ref('全部'), now = ref(new Date()), selectedEvent = ref<Notice>(), elapsed = ref(0)
const clock = computed(() => now.value.toLocaleTimeString('zh-CN', { hour12: false, timeZone: 'Asia/Shanghai' }))
const dateLabel = computed(() => now.value.toLocaleDateString('zh-CN', { month: 'long', day: 'numeric', weekday: 'long', timeZone: 'Asia/Shanghai' }))
const initialTime = (minutes: number) => new Date(Date.now() - minutes * 60000).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Asia/Shanghai' })
const events = ref<Notice[]>([
  { id: 3, title: '宝宝翻了个身', detail: '检测到活动 · 演示事件', time: initialTime(8), kind: '活动' },
  { id: 2, title: '检测到哭声', detail: '持续约 12 秒 · 演示事件', time: initialTime(26), kind: '声音' },
  { id: 1, title: '房间温度恢复舒适', detail: '温度 24.6°C · 演示事件', time: initialTime(53), kind: '环境' },
])
const shownEvents = computed(() => events.value.filter(e => filter.value === '全部' || e.kind === filter.value))
const tabs: {id: Tab; name: string; icon: string}[] = [{id:'home',name:'首页',icon:'home'},{id:'monitor',name:'看宝宝',icon:'camera'},{id:'events',name:'消息',icon:'bell'},{id:'profile',name:'我的',icon:'user'}]
let tick: ReturnType<typeof setInterval>, toastTimer: ReturnType<typeof setTimeout>, audioTimer: ReturnType<typeof setInterval> | undefined
let audio: AudioContext | undefined, note = 0
function notify(message: string) { toast.value = message; clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.value = '', 3000) }
function openMonitor(name = deviceName.value) { deviceName.value = name; tab.value = 'monitor' }
function addEvent(title: string, detail: string, kind: string) {
  events.value.unshift({id:Date.now(),title,detail,time:clock.value.slice(0,5),kind})
  events.value = events.value.slice(0, 50)
}
function simulateCry() {
  addEvent('检测到哭声', '手动触发的模拟声音事件', '声音')
  notify(cryAlerts.value ? '检测到哭声，请查看宝宝状态' : '模拟事件已记录，哭声提醒已关闭')
}
function addDevice() {
  const name = newName.value.trim()
  if (!name) return
  extraDevice.value = name; sheet.value = ''; notify('演示设备已添加到我的家')
}
async function toggleMusic() {
  if (music.value) { stopAudio(); return }
  try {
    audio = new AudioContext(); await audio.resume()
    if (audio.state !== 'running') { stopAudio(); notify('浏览器未能开启声音，请重试'); return }
    music.value = true
    const melody = [261.63,261.63,392,392,440,440,392,349.23,349.23,329.63,329.63,293.66,293.66,261.63]
    const play = () => {
      if (!audio) return
      const oscillator = audio.createOscillator(), gain = audio.createGain(), start = audio.currentTime
      oscillator.type = 'sine'; oscillator.frequency.value = melody[note++ % melody.length]!
      gain.gain.setValueAtTime(0,start); gain.gain.linearRampToValueAtTime(.055,start+.04); gain.gain.exponentialRampToValueAtTime(.001,start+.65)
      oscillator.connect(gain); gain.connect(audio.destination); oscillator.start(start); oscillator.stop(start+.7)
    }
    play(); audioTimer = setInterval(play, 720); notify('本机播放摇篮曲，未发送到设备')
  } catch { stopAudio(); notify('浏览器暂不支持声音播放') }
}
function stopAudio() { clearInterval(audioTimer); audioTimer = undefined; void audio?.close(); audio = undefined; music.value = false }
function capture() {
  const svg = document.querySelector('.baby-monitor .nursery-scene')
  if (!svg) return
  const url = URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(svg)], {type:'image/svg+xml;charset=utf-8'}))
  const link = document.createElement('a'); link.href = url; link.download = '星云宝宝-演示截图.svg'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000)
  notify('演示画面已保存为 SVG 插画')
}
function toggleRecording() {
  recording.value = !recording.value
  if (recording.value) { elapsed.value = 0; notify('开始演示录制计时，不生成视频') }
  else { addEvent('演示录制已结束', `录制操作体验 · ${elapsed.value} 秒，未生成视频`, '活动'); notify('计时结束，操作已记录在消息中') }
}
function talk() { talking.value = !talking.value; notify(talking.value ? '演示对讲中，未采集麦克风或连接设备' : '演示对讲已结束') }
function keyboard(event: KeyboardEvent) { if (event.key === 'Escape') { sheet.value = ''; expanded.value = false } }
onMounted(() => {
  try {
    const saved = JSON.parse(localStorage.getItem('nebula-baby-demo-v1') || 'null')
    if (saved && typeof saved === 'object') {
      if(typeof saved.extraDevice === 'string') extraDevice.value = saved.extraDevice.slice(0,24)
      if(typeof saved.cryAlerts === 'boolean') cryAlerts.value = saved.cryAlerts
      if(typeof saved.motionAlerts === 'boolean') motionAlerts.value = saved.motionAlerts
      if(typeof saved.temperatureAlerts === 'boolean') temperatureAlerts.value = saved.temperatureAlerts
      if(['低','适中','高'].includes(saved.sensitivity)) sensitivity.value = saved.sensitivity
    }
  } catch { /* A browser with storage disabled can still run the demo. */ }
  tick = setInterval(() => { if (!paused.value) now.value = new Date(); if(recording.value) elapsed.value++ }, 1000)
  window.addEventListener('keydown', keyboard)
})
watch([extraDevice,cryAlerts,motionAlerts,temperatureAlerts,sensitivity], () => {
  try { localStorage.setItem('nebula-baby-demo-v1', JSON.stringify({ extraDevice:extraDevice.value, cryAlerts:cryAlerts.value, motionAlerts:motionAlerts.value, temperatureAlerts:temperatureAlerts.value, sensitivity:sensitivity.value })) } catch { notify('浏览器未允许保存设置，本次体验仍然有效') }
})
watch(tab, () => { expanded.value = false; talking.value = false; sound.value = false; if(recording.value) toggleRecording(); stopAudio() })
onUnmounted(() => { clearInterval(tick); clearTimeout(toastTimer); stopAudio(); window.removeEventListener('keydown',keyboard) })
</script>

<template>
  <main class="baby-experience">
    <aside class="experience-intro">
      <RouterLink to="/developer" class="experience-brand"><span class="baby-brand-mark"><Icon name="moon" :size="24"/></span> NEBULA <span>星云 IoT</span></RouterLink>
      <div class="intro-body"><p class="intro-eyebrow">A LITTLE CLOSER, ALWAYS.</p><h1>每个小小动静，<br>都放在心上。</h1><p class="intro-description">星云宝宝 · 智能婴儿监视器<br>让陪伴，看得见，也听得见。</p><div class="intro-tags"><span><Icon name="camera" :size="16"/> 随时看护</span><span><Icon name="bell" :size="16"/> 贴心提醒</span><span><Icon name="heart" :size="16"/> 安心陪伴</span></div><div class="experience-guide"><small>APP 交互体验 / 01</small><strong>{{ platformMode ? '填写设备 ID，开始平台联调' : tab === 'monitor' ? '打开监视器，试试夜视与摇篮曲' : tab === 'events' ? '查看宝宝动态，模拟一条哭声提醒' : tab === 'profile' ? '按照你的习惯，设置看护提醒' : '从「宝宝的房间」，开始体验' }}</strong><p>{{ platformMode ? '绑定平台设备 ID，加载设备的物模型。' : '界面演示使用插画和模拟数据。' }}<br>{{ platformMode ? 'MQTT 上报实时可见，App 控制通过平台下发。' : '切换到平台设备可联调真实上下行。' }}</p></div></div>
      <footer class="experience-footer"><span>BUILT WITH NEBULA IoT</span><RouterLink to="/developer">开发者中心 ↗</RouterLink></footer>
    </aside>

    <section class="phone-stage" aria-label="星云宝宝 App 体验">
      <div class="phone-shell">
        <div class="phone-status"><strong>9:41</strong><span class="phone-island"></span><span><Icon name="wifi" :size="15"/> ▰</span></div>
        <div class="baby-app">
          <header class="baby-header">
            <template v-if="platformMode"><div><span class="baby-kicker">NEBULA / CONNECTED CARE</span><h2>{{ tab === 'home' ? '我的家' : tab === 'monitor' ? '看宝宝' : tab === 'events' ? '设备动态' : '我的设备' }}</h2></div><button class="baby-icon-button filled" aria-label="绑定平台设备" @click="platformPanel?.openBinding()"><Icon name="plus"/></button></template>
            <template v-else-if="tab === 'home'"><div><span class="baby-kicker">{{ dateLabel }}</span><h2>我的家 <span class="home-chevron">⌄</span></h2></div><button class="baby-icon-button filled" aria-label="添加设备" @click="sheet = 'add'"><Icon name="plus"/></button></template>
            <template v-else-if="tab === 'monitor'"><button class="baby-icon-button" aria-label="返回首页" @click="tab = 'home'"><Icon name="back"/></button><div class="monitor-heading"><h2>{{ deviceName }}</h2><span><i class="online-dot"/> 在线 · 演示设备</span></div><button class="baby-icon-button" aria-label="设备设置" @click="sheet = 'settings'"><Icon name="settings"/></button></template>
            <template v-else><div><span class="baby-kicker">{{ tab === 'events' ? 'EVERY LITTLE MOMENT' : 'HERE FOR YOUR FAMILY' }}</span><h2>{{ tab === 'events' ? '宝宝动态' : '我的' }}</h2></div><span class="header-flower">✳</span></template>
          </header>

          <div class="baby-content">
            <ConsumerPlatformPanel v-if="platformMode" ref="platformPanel" :tab="tab" @connected="platformName = $event"/>
            <div class="mode-switch"><button @click="platformMode = !platformMode; tab = 'home'">{{ platformMode ? '查看界面演示' : '连接平台设备' }} →</button></div>
            <template v-if="!platformMode && tab === 'home'">
              <section class="welcome-note"><span class="welcome-moon"><Icon name="moon" :size="27"/></span><div><strong>小小的梦，大大的安心</strong><p>房间很舒适，陪宝宝做个好梦。</p></div><span class="sparkle">✧</span></section>
              <div class="baby-section-title"><h3>我的设备 <small>{{ extraDevice ? '02' : '01' }}</small></h3><span>全部房间</span></div>
              <button class="home-device" @click="openMonitor('宝宝的房间')"><div class="device-preview"><NurseryScene moving/><span class="preview-badge"><i/> 演示画面</span><span class="preview-play"><Icon name="play" :size="20"/></span></div><div class="device-info"><div><strong>宝宝的房间</strong><span><i class="online-dot"/> 婴儿监视器 · 在线</span></div><Icon name="chevron" :size="18"/></div><div class="device-metrics"><span><Icon name="thermometer" :size="16"/>24.6° <small>室温</small></span><span><Icon name="drop" :size="15"/>56% <small>湿度</small></span><span><i class="quiet-dot"/>环境安静</span></div></button>
              <button v-if="extraDevice" class="extra-device" @click="openMonitor(extraDevice)"><span class="extra-camera"><Icon name="camera" :size="26"/></span><div><strong>{{ extraDevice }}</strong><small>婴儿监视器 · 演示设备</small></div><Icon name="chevron" :size="18"/></button>
              <button class="add-device-card" @click="sheet = 'add'"><Icon name="plus" :size="19"/> 添加新设备 <span>让关心多一个角度</span></button>
              <div class="baby-section-title"><h3>最近动态</h3><button @click="tab = 'events'">查看全部 <Icon name="chevron" :size="13"/></button></div>
              <button v-for="event in events.slice(0,2)" :key="event.id" class="mini-event" @click="selectedEvent = event; sheet = 'event'"><span class="event-icon" :class="{ peach: event.kind === '声音' }"><Icon :name="event.kind === '声音' ? 'sound' : 'moon'" :size="19"/></span><div><strong>{{ event.title }}</strong><small>{{ event.detail }}</small></div><time>{{ event.time }}</time></button>
              <div class="care-footnote"><Icon name="shield" :size="13"/> 每一份关心，都有回应</div>
            </template>

            <template v-else-if="!platformMode && tab === 'monitor'">
              <section class="baby-monitor" :class="{ expanded }"><div class="monitor-canvas"><NurseryScene :night="night" :moving="!paused"/><div class="monitor-top"><span><i :class="{ stopped: paused }"/> {{ paused ? '已暂停' : 'DEMO' }}</span><time>{{ clock }}</time></div><div class="monitor-bottom"><span>{{ night ? '夜视演示' : '插画演示 · 非实时视频' }}</span><button :aria-label="expanded ? '退出大画面' : '放大画面'" @click="expanded = !expanded"><Icon :name="expanded ? 'close' : 'expand'" :size="19"/></button></div><span v-if="recording" class="recording-badge">● 演示计时 {{ elapsed }}s</span></div><div class="monitor-stream"><span><i class="online-dot"/>{{ paused ? '预览已暂停' : '预览运行中' }}</span><button @click="paused = !paused">{{ paused ? '继续预览' : '暂停预览' }}</button></div></section>
              <div class="monitor-comfort"><span><Icon name="thermometer" :size="19"/><strong>24.6<small>°C</small></strong><small>室温舒适</small></span><span><Icon name="drop" :size="18"/><strong>56<small>%</small></strong><small>湿度适宜</small></span><span><Icon name="sound" :size="19"/><strong>32<small>dB</small></strong><small>环境安静</small></span></div>
              <div class="monitor-controls"><button :class="{ active: sound }" :aria-pressed="sound" @click="sound = !sound; notify(sound ? '监听已开启（演示无环境音轨）' : '监听已关闭')"><span><Icon :name="sound ? 'sound' : 'mute'"/></span>{{ sound ? '关闭监听' : '声音监听' }}</button><button @click="capture"><span><Icon name="photo"/></span>截图</button><button :class="{ active: recording }" :aria-pressed="recording" @click="toggleRecording"><span><Icon name="record"/></span>{{ recording ? '结束计时' : '演示录像' }}</button><button :class="{ active: night }" :aria-pressed="night" @click="night = !night"><span><Icon :name="night ? 'sun' : 'moon'"/></span>{{ night ? '关闭夜视' : '夜视模式' }}</button></div>
              <button class="talk-button" :class="{ talking }" :aria-pressed="talking" @click="talk"><Icon name="mic" :size="23"/>{{ talking ? '结束演示对讲' : '和宝宝说句话' }}<small>对讲体验</small></button>
              <button class="lullaby-card" :class="{ playing: music }" :aria-pressed="music" @click="toggleMusic"><span class="music-disc"><Icon name="music" :size="23"/></span><div><strong>{{ music ? '小星星 · 正在播放' : '给宝宝一首摇篮曲' }}</strong><small>本机试听 · 轻柔陪伴</small></div><span class="music-play">{{ music ? 'Ⅱ' : '▷' }}</span></button>
              <p class="monitor-note">所有读数均为模拟数据，控制操作不会发送到真实设备。</p>
            </template>

            <template v-else-if="!platformMode && tab === 'events'">
              <div class="events-summary"><span class="summary-orbit"><Icon name="heart" :size="30"/></span><div><h3>不错过每一个小瞬间</h3><p>今日 {{ events.length }} 条演示动态</p></div></div>
              <div class="event-filters" aria-label="事件类型"><button v-for="kind in ['全部','声音','活动','环境']" :key="kind" :class="{ selected: filter === kind }" :aria-pressed="filter === kind" @click="filter = kind">{{ kind }}</button></div>
              <div class="baby-section-title"><h3>今天 <small>{{ dateLabel }}</small></h3></div>
              <button v-for="event in shownEvents" :key="event.id" class="event-card" @click="selectedEvent = event; sheet = 'event'"><div class="event-thumbnail"><NurseryScene/><span><Icon name="play" :size="16"/></span></div><div><strong>{{ event.title }}</strong><p>宝宝的房间</p><small>{{ event.time }} · {{ event.kind }}提醒</small></div><Icon name="chevron" :size="16"/></button>
              <p v-if="!shownEvents.length" class="empty-events">今天还没有这类动态。</p>
              <button class="simulate-event" @click="simulateCry"><Icon name="bell" :size="17"/> 模拟一条哭声事件</button><p class="monitor-note">用于体验提醒流程，不进行真实声音识别。</p>
            </template>

            <template v-else-if="!platformMode">
              <section class="profile-card"><span class="profile-avatar"><Icon name="user" :size="32"/></span><div><h3>体验用户</h3><p>和家人一起，守护小小世界</p></div><span class="demo-pill">DEMO</span></section>
              <div class="family-card"><span><Icon name="home" :size="26"/></span><div><strong>我的家</strong><p>{{ extraDevice ? 2 : 1 }} 台演示设备 · 本地体验</p></div><Icon name="heart" :size="24"/></div>
              <div class="baby-section-title"><h3>看护设置</h3></div><section class="settings-group"><label><span><Icon name="sound"/>哭声提醒</span><input v-model="cryAlerts" type="checkbox" role="switch" aria-label="哭声提醒"/></label><label><span><Icon name="camera"/>活动提醒</span><input v-model="motionAlerts" type="checkbox" role="switch" aria-label="活动提醒"/></label><label><span><Icon name="thermometer"/>温湿度提醒</span><input v-model="temperatureAlerts" type="checkbox" role="switch" aria-label="温湿度提醒"/></label><label><span><Icon name="bell"/>检测灵敏度</span><select v-model="sensitivity" aria-label="检测灵敏度"><option>低</option><option>适中</option><option>高</option></select></label></section>
              <button class="profile-about" @click="sheet = 'about'"><span><Icon name="shield"/>关于体验版</span><Icon name="chevron" :size="17"/></button><p class="monitor-note">提醒偏好保存在本机浏览器。<br>尚未连接账号、云端推送或真实检测服务。</p><div class="profile-wordmark"><Icon name="moon" :size="25"/><strong>星云宝宝</strong><small>每一刻，安心相伴。</small></div>
            </template>
          </div>
          <nav class="baby-tabs" aria-label="App 导航"><button v-for="item in tabs" :key="item.id" :class="{ selected: tab === item.id }" :aria-current="tab === item.id ? 'page' : undefined" @click="tab = item.id"><span><Icon :name="item.icon" :size="23"/><i v-if="item.id === 'events'"/></span>{{ item.name }}</button></nav>
          <div class="phone-home-indicator"><span/></div>
          <Transition name="baby-toast"><div v-if="toast" class="baby-toast-message" role="status">{{ toast }}</div></Transition>
          <el-dialog :model-value="Boolean(sheet)" :title="sheet === 'add' ? '添加设备' : sheet === 'settings' ? '设备设置' : sheet === 'event' ? '动态详情' : '关于星云宝宝'" width="min(360px, calc(100vw - 32px))" class="baby-dialog" :close-on-click-modal="true" @update:model-value="(value: boolean) => { if (!value) sheet = '' }">
            <form v-if="sheet === 'add'" class="baby-sheet-form" @submit.prevent="addDevice"><span class="sheet-camera"><Icon name="camera" :size="38"/></span><p>为家里增加一个安心的角度</p><label>设备类型<select v-model="deviceType"><option>婴儿监视器</option></select></label><label>设备名称<input v-model="newName" maxlength="24" required placeholder="例如：儿童房监视器"/></label><div class="sheet-demo-note">演示模式：添加虚拟设备，无需配网。添加操作不创建平台设备。</div><button class="sheet-primary" type="submit">添加演示设备</button></form>
            <div v-else-if="sheet === 'settings'" class="baby-sheet-form"><p>{{ deviceName }} · 演示设备</p><label>夜视预览<input v-model="night" type="checkbox" role="switch"/></label><label>哭声提醒<input v-model="cryAlerts" type="checkbox" role="switch"/></label><label>活动提醒<input v-model="motionAlerts" type="checkbox" role="switch"/></label><button class="sheet-primary" @click="sheet = ''; notify('设置已更新')">完成</button></div>
            <div v-else-if="sheet === 'event' && selectedEvent" class="baby-sheet-form"><div class="event-detail-scene"><NurseryScene/></div><strong>{{ selectedEvent.title }}</strong><p>{{ selectedEvent.time }} · 宝宝的房间</p><p>{{ selectedEvent.detail }}</p><div class="sheet-demo-note">这是模拟事件与插画预览，未接入事件录像回放。</div><button class="sheet-primary" @click="sheet = ''; openMonitor('宝宝的房间')">前往监看</button></div>
            <div v-else class="baby-sheet-form"><p>星云宝宝是 practice 项目的 C 端交互体验版。</p><p>当前可以体验设备列表、监看操作、夜视效果、摇篮曲试听、消息和本地设置。</p><div class="sheet-demo-note">全部设备和事件均为模拟。后续接入用户身份、设备绑定、WebRTC 视频与实时状态订阅。</div><button class="sheet-primary" @click="sheet = ''">我知道了</button></div>
          </el-dialog>
        </div>
      </div><p class="stage-caption"><span/> {{ platformMode ? (platformName ? '平台设备已关联 · 按物模型联调' : '平台联调模式 · 等待绑定设备') : '界面演示 · 所有设备均为模拟' }}</p>
    </section>
  </main>
</template>

